MeasuredTripleSelections:
∃ select : List Bool × List Bool → List Bool,
      PEqualNP.Library.ComputableInPolyTime PEqualNP.Library.encodePair (fun x : List Bool => x) select ∧
      ∀ (groups : List (List Bool × List Bool × List Bool)) (seed : List Bool),
        select (groups.foldr (fun group rest =>
          let bc := List.replicate group.2.1.length true ++ false :: (group.2.1 ++ group.2.2)
          let abc := List.replicate group.1.length true ++ false :: (group.1 ++ bc)
          List.replicate abc.length true ++ false :: (abc ++ rest)) [], seed) =
          (List.range groups.length).flatMap (fun i =>
            let group := groups[i]?.getD ([],[],[])
            if seed.getD (2*i) false then group.1
            else if seed.getD (2*i+1) false then group.2.1 else group.2.2)

ThreeClauseBranching2SAT:
∀ (q : Polynomial ℕ), ∃ D : Language Bool, D ∈ PEqualNP.Library.P ∧
      ∀ (φ : PEqualNP.Search.CNF) (groups : List (PEqualNP.Search.Literal × PEqualNP.Search.Literal × PEqualNP.Search.Literal)),
        let packed := (groups.map (fun group =>
          (PEqualNP.Search.encodeClause [group.1], PEqualNP.Search.encodeClause [group.2.1], PEqualNP.Search.encodeClause [group.2.2]))).foldr (fun group rest =>
            let bc := List.replicate group.2.1.length true ++ false :: (group.2.1 ++ group.2.2)
            let abc := List.replicate group.1.length true ++ false :: (group.1 ++ bc)
            List.replicate abc.length true ++ false :: (abc ++ rest)) []
        let query := List.replicate (PEqualNP.Search.encodeCNF φ).length true ++ false :: (PEqualNP.Search.encodeCNF φ ++ packed)
        PEqualNP.Search.IsKCNF 2 φ → 2 ^ (2 * groups.length + 1) ≤ q.eval query.length →
          (query ∈ D ↔ PEqualNP.Search.Satisfiable (φ ++ groups.map (fun group => [group.1,group.2.1,group.2.2])))
